class Solution {
public:
    int maxLength(std::vector<std::string>& arr) {
        std::vector<int> masks = {0};
        for (const auto& s : arr) {
            int mask = 0;
            bool dup = false;
            for (char c : s) {
                int bit = 1 << (c - 'a');
                if (mask & bit) {
                    dup = true;
                    break;
                }
                mask |= bit;
            }
            if (dup) continue;
            int sz = masks.size();
            for (int i = 0; i < sz; ++i) {
                if ((masks[i] & mask) == 0) {
                    masks.push_back(masks[i] | mask);
                }
            }
        }
        int ans = 0;
        for (int m : masks) {
            ans = std::max(ans, __builtin_popcount(m));
        }
        return ans;
    }
};

class Solution {
    public int maxLength(java.util.List<String> arr) {
        java.util.List<Integer> masks = new java.util.ArrayList<>();
        masks.add(0);
        for (String s : arr) {
            int mask = 0;
            boolean dup = false;
            for (char c : s.toCharArray()) {
                int bit = 1 << (c - 'a');
                if ((mask & bit) != 0) {
                    dup = true;
                    break;
                }
                mask |= bit;
            }
            if (dup) continue;
            int sz = masks.size();
            for (int i = 0; i < sz; i++) {
                if ((masks.get(i) & mask) == 0) {
                    masks.add(masks.get(i) | mask);
                }
            }
        }
        int ans = 0;
        for (int m : masks) {
            ans = Math.max(ans, Integer.bitCount(m));
        }
        return ans;
    }
}

var maxLength = function(arr) {
    const masks = [0];
    for (const s of arr) {
        let mask = 0;
        let dup = false;
        for (let i = 0; i < s.length; i++) {
            const bit = 1 << (s.charCodeAt(i) - 97);
            if (mask & bit) {
                dup = true;
                break;
            }
            mask |= bit;
        }
        if (dup) continue;
        const sz = masks.length;
        for (let i = 0; i < sz; i++) {
            if ((masks[i] & mask) === 0) {
                masks.push(masks[i] | mask);
            }
        }
    }
    const popcount = (x) => {
        let cnt = 0;
        while (x > 0) {
            cnt += x & 1;
            x >>= 1;
        }
        return cnt;
    };
    let ans = 0;
    for (const m of masks) ans = Math.max(ans, popcount(m));
    return ans;
};
